def render(pages, component_render):
 # Общая оболочка документации, единые стили и навигация.
 template = component_render(pages[0])
 start = template.split('  <header class="sc-hero sc-hero--component">')[0]
 start = start.replace('<body class="dk-page dk-glass">', '<body class="dk-page dk-glass sc-guide">')
 start = start.replace('<title>Кнопка · dashboard-kit</title>', '<title>Обзор · dashboard-kit</title>')
 # Static hero illustration; the task form is the only page-specific component.
 start = start.replace('</head>', '''<link rel="stylesheet" href="css/page.overview.css?v=20261029-illustration">
<script src="js/dk-form.js" defer></script>
<script src="js/docs-overview.js?v=20261029-illustration" defer></script>
</head>''')
 start = start.replace('tools/component_pages/p1_controls.py', 'tools/docs_guide.py')
 rules = ''.join('<div class="sc-note"><h3>'+e(title)+'</h3><ul class="sc-list">'+''.join('<li>'+e(x)+'</li>' for x in items)+'</ul></div>' for title,items in RULES)
 policy = json.loads((Path(__file__).resolve().parent.parent/'.ai/project/uiux-policy.json').read_text())
 heuristics = ''.join('<tr><td>'+e(h['name'])+'</td><td>'+e(h['requirement'])+'</td></tr>' for h in policy['heuristics'])
 patterns = ''.join('<details class="dk-data-summary" id="pattern-'+e(row['id'])+'"><summary>'+e(row['title'])+'</summary><ul class="sc-list">'+''.join('<li>'+e(x)+'</li>' for x in row['rules'])+'</ul><p>Избегать: '+e(row['example_bad'])+'</p><p>Выбирать: '+e(row['example_good'])+'</p><p>Проверка: '+e(row['review'])+'</p><details class="dk-data-summary"><summary>Критерии ревью реализации</summary><p>'+e(', '.join(row['constitution']))+'</p></details><p>'+ ' · '.join('<a href="component-'+e(slug)+'.html">'+e(next(p['title'] for p in pages if p['slug']==slug))+'</a>' for slug in row['components'])+'</p><p><a href="'+e(row['source'])+'">Материал UPROCK</a></p></details>' for row in policy['patterns'])
 guidance = ''.join('<details class="dk-data-summary"><summary>'+e(row['name'])+'</summary><p>'+e(row['apply'])+'</p><p>'+e(row['boundary'])+'</p><p><a href="'+e(row['source'])+'">Публичное описание TypeUI</a></p></details>' for row in policy.get('design_guidance', []))
 catalog = ''
 for group in ['Композиция', 'Управление', 'Фильтры', 'Данные', 'Визуализация', 'Обратная связь', 'Утилиты']:
  rows = ''.join('<tr><td><a href="component-'+e(p['slug'])+'.html">'+e(p['title'])+'</a></td><td>'+p['purpose']+'</td><td>'+e(p['status'])+'</td></tr>' for p in pages if p['group']==group)
  catalog += '<h3>'+e(group)+'</h3><div class="dk-tablewrap"><table class="dk-table sc-api"><thead><tr><th scope="col">Компонент</th><th scope="col">Назначение</th><th scope="col">Статус</th></tr></thead><tbody>'+rows+'</tbody></table></div>'
 foundation = ''
 for p in MP.PARTS:
  use = ''.join('<li>'+e(x)+'</li>' for x in p.get('use_when',[]))
  refs = ''.join('<li><a href="'+e(x)+'">'+e(x)+'</a></li>' for x in p.get('docs',[]))
  foundation += '<details class="dk-data-summary" id="foundation-'+e(p['id'])+'"><summary>'+e(p['title'])+'</summary><p>'+e(p['purpose'])+'</p><p>Статус: '+e(p['status'])+'</p><h3>Когда использовать</h3><ul class="sc-list">'+use+'</ul><h3>Правила и поведение</h3><ul class="sc-list">'+''.join('<li>'+e(x)+'</li>' for x in p.get('rules',[]))+'</ul><p>Классы: '+', '.join('<code>'+e(x)+'</code>' for x in p.get('owns',[]))+'</p><p>Скрипты: '+e(', '.join(p.get('scripts',[])) or 'не требуются')+'</p><ul class="sc-list">'+refs+'</ul></details>'
 return start + f'''<header class="sc-hero sc-hero--overview">
<div class="sc-overview-intro">
<div class="sc-overview-copy"><p class="sc-hero__o">dashboard-kit</p><h1>От вашей задачи<br> к дашборду</h1><p class="sc-hero__lead">Соберите дашборд с помощью готовых компонентов, визуального языка и примеров. Codex, Claude или другой ИИ-помощник подберёт инструменты под вашу задачу.</p>
<div class="sc-overview-actions"><a class="dk-btn dk-btn--primary" href="#start">Собрать дашборд <svg class="dk-i" aria-hidden="true"><use href="#ti-chevron-right"/></svg></a><a class="dk-btn" href="#workflow">Как работать с ИИ <svg class="dk-i" aria-hidden="true"><use href="#ti-external-link"/></svg></a></div></div>
<div class="sc-overview-art" aria-hidden="true"><img src="assets/dashboard-kit-hero.png" width="1254" height="1254" alt="" fetchpriority="high" decoding="async"></div></div>
<ol class="sc-overview-steps dk-widget" aria-label="Как собрать дашборд"><li><span class="sc-step-emoji" aria-hidden="true">📝</span><div><strong>1. Опишите задачу</strong><span>Какой дашборд нужен и кому он поможет.</span></div></li><li><span class="sc-step-emoji" aria-hidden="true">🗂️</span><div><strong>2. Передайте данные</strong><span>Файл, источник или описание будущих данных.</span></div></li><li><span class="sc-step-emoji" aria-hidden="true">✨</span><div><strong>3. Получите дашборд</strong><span>Помощник подберёт компоненты и проверит результат.</span></div></li></ol>
<div class="sc-overview-examples" id="overview-examples"><div class="sc-overview-section-head"><h2><span class="sc-doc-emoji" aria-hidden="true">🖥️</span>Примеры дашбордов</h2><button class="dk-btn" type="button" data-more-examples aria-expanded="false" aria-controls="overview-more-examples">Все примеры <svg class="dk-i" aria-hidden="true"><use href="#ti-chevron-right"/></svg></button></div><p>Посмотрите, как компоненты работают вместе. Данные в примерах демонстрационные.</p>
<div class="sc-example-cards">{''.join('<a class="dk-widget sc-example-card" href="'+href+'.html"><img src="assets/examples/'+href+'-dark.png" data-example-image="'+href+'" width="640" height="450" alt="" loading="lazy"><strong>'+title+'</strong><span>'+description+'</span></a>' for href,title,description in [('regions','Мониторинг регионов','Карта, события, метрики'),('accidents','Аварии и инциденты','Список, фильтры, динамика'),('calendar','Календарь событий','Периоды, категории, работы'),('family-mortgage','Семейная ипотека','Показатели, регионы, план')])}</div>
<div class="sc-overview-more" id="overview-more-examples" hidden><a class="dk-btn" href="dashboard.html">Мониторинг показателей <svg class="dk-i" aria-hidden="true"><use href="#ti-arrow-up-right"/></svg></a><a class="dk-btn" href="reference-dashboard.html">Данные и действия <svg class="dk-i" aria-hidden="true"><use href="#ti-arrow-up-right"/></svg></a><a class="dk-btn" href="ai-value.html">Польза AI <svg class="dk-i" aria-hidden="true"><use href="#ti-arrow-up-right"/></svg></a></div></div>
<div class="dk-widget sc-overview-catalog"><span class="sc-catalog-emoji" aria-hidden="true">📖</span><div><h2>Справочник компонентов</h2><p>{len(pages)} компонентов: возможности, примеры использования и правила.</p></div><a class="dk-btn" href="#catalog">Открыть справочник <svg class="dk-i" aria-hidden="true"><use href="#ti-chevron-right"/></svg></a></div>
</header>
<section class="sc-sec" id="start"><h2><span class="sc-doc-emoji" aria-hidden="true">🛠️</span>Собрать дашборд</h2><p>Подготовьте задачу и получите запрос для Codex, Claude или другого ИИ-помощника. Компоненты и графики он подберёт по правилам кита.</p>
<form class="dk-form dk-form--one sc-task-form" id="dashboard-task-form"><div class="dk-form__alarm" hidden></div>
<div class="dk-ff"><label class="dk-label" for="task-goal">Какой ответ нужен <span class="dk-label__req">обязательно</span></label><textarea class="dk-area" id="task-goal" name="goal" required maxlength="4000" placeholder="Хочу видеть выполнение плана продаж по регионам и понимать причины отклонений"></textarea></div>
<div class="dk-ff"><label class="dk-label" for="task-audience">Кто будет пользоваться <span class="dk-label__opt">необязательно</span></label><div class="dk-field"><input id="task-audience" name="audience" maxlength="500" placeholder="Руководители региональных команд"></div></div>
<div class="dk-ff"><label class="dk-label" for="task-data">Какие данные есть <span class="dk-label__req">обязательно</span></label><textarea class="dk-area" id="task-data" name="data" required maxlength="4000" aria-describedby="task-data-hint" placeholder="CSV с продажами по месяцам и регионам; есть факт, план и категория продукта. Или: данных пока нет"></textarea><p class="dk-hint" id="task-data-hint">Укажите файл, доступный источник или напишите, что данных пока нет. Сам файл приложите в чате с помощником.</p></div>
<div class="dk-ff"><label class="dk-label" for="task-context">Период и ограничения <span class="dk-label__opt">необязательно</span></label><textarea class="dk-area" id="task-context" name="context" maxlength="2000" placeholder="По месяцам за 2026 год. Нужны сравнение с планом, фильтр по региону и работа на телефоне"></textarea></div>
<div class="dk-form__foot"><button class="dk-btn dk-btn--primary" type="submit">Подготовить запрос <svg class="dk-i" aria-hidden="true"><use href="#ti-chevron-right"/></svg></button></div></form>
<div class="sc-task-result" data-task-result hidden><h3 tabindex="-1" data-task-result-title>Запрос готов</h3><p>Откройте проект с dashboard-kit в Codex или Claude Code. В другом инструменте передайте помощнику файлы кита. Скопируйте запрос ниже и приложите указанные данные.</p><pre class="sc-code"><code id="dashboard-task-prompt"></code></pre><div class="sc-overview-actions"><button class="dk-btn dk-btn--primary" type="button" data-copy-task>Скопировать запрос</button><button class="dk-btn" type="button" data-download-task>Скачать задание .txt <svg class="dk-i" aria-hidden="true"><use href="#ti-download"/></svg></button></div><p class="sc-copy-status" role="status" aria-live="polite" data-copy-task-status></p></div>
<h3>Если данных пока нет</h3><p>Так и напишите в поле данных. Помощник предложит структуру и сможет собрать прототип на явно обозначенных примерах. Реальный источник подключается следующим шагом.</p>
<h3>Уточняйте результат обычными словами</h3><p>Например: «Покажи сравнение с прошлым месяцем», «Добавь детализацию по регионам» или «Главное здесь — причины отклонений».</p></section>
<section class="sc-sec" id="development"><h2><span class="sc-doc-emoji" aria-hidden="true">💻</span>Стек и библиотеки</h2><p>Dashboard-kit — собственная библиотека интерфейса на HTML, CSS и JavaScript. HTML задаёт структуру, CSS — оформление и адаптацию, JavaScript — действия, состояние и обновление данных. React, Vue, Angular и Bootstrap в текущем ките не используются.</p>
<h3>Нужно ли менять стек</h3><p>Текущий кит остаётся на HTML, CSS и JavaScript: его можно использовать для самостоятельных дашбордов и подключать к приложению. React или Vue имеет смысл выбирать на уровне конкретного продукта, если этого требует его архитектура. Для встраивания нужно проверить адаптер, обновление данных и освобождение ресурсов — сама смена фреймворка эти задачи не решает.</p><h3>Что своё, а что готовое</h3><div class="dk-tablewrap"><table class="dk-table sc-api"><thead><tr><th scope="col">Часть</th><th scope="col">Реализация</th><th scope="col">За что отвечает</th></tr></thead><tbody>
<tr><td>Компоненты и токены</td><td>Собственный код dashboard-kit</td><td>Кнопки, таблицы, фильтры, виджеты, темы, отступы и состояния.</td></tr>
<tr><td>Графики и географическая карта</td><td>Apache ECharts · локальная сборка</td><td>Рисует графики; обёртки кита задают темы, форматирование и поведение.</td></tr>
<tr><td>Выбор даты и периода</td><td>Air Datepicker</td><td>Календарь внутри выбора периода. Календарь работ — отдельный компонент кита.</td></tr>
<tr><td>Иконки</td><td>Tabler Icons</td><td>SVG-значки, собранные в локальный спрайт.</td></tr>
<tr><td>Шрифт</td><td>Golos Text</td><td>Локальные файлы шрифта для русского и латинского текста.</td></tr>
</tbody></table></div><p>Зависимости лежат в <code>vendor/</code>, их лицензии — в <code>vendor/licenses/</code>. Браузеру не нужно скачивать их с внешнего CDN. VKUI и другие дизайн-системы, упомянутые в материалах, — ориентиры документации, а не подключённые UI-библиотеки.</p>
<h3>Граница ответственности</h3><p>Кит отвечает за интерфейс. Приложение подключает API, авторизацию, права доступа, расчёт метрик и сохранение данных. Экспорт и сохранённые виды используют доступные приложению данные; серверное хранение подключается отдельно.</p>
<h3 id="development--connect">Подключение и проверка</h3><ol class="sc-list"><li>Найти нужные части: <code>python3 tools/kit.py list</code>, затем <code>python3 tools/kit.py show table chart</code>.</li><li>Получить теги подключения: <code>python3 tools/kit.py head table chart</code>. Тема подключается первой; <code>dk-util</code> — до остальных компонентов. Стили: primitives → semantic → components.</li><li>Взять пример со страницы компонента и подключить свои данные. Строки экранировать через <code>dkEsc</code>, числа форматировать через <code>dkFmt</code>.</li><li>Открыть через локальный сервер: <code>python3 tools/preview.py --port 8771</code>. Для карты и загрузки данных нужен HTTP.</li><li>Запустить <code>python3 tools/check.py --fast</code>; полную проверку — <code>python3 tools/check.py</code> с Node.js 22+ и Chrome. Расширенный набор браузерных регрессий — <code>python3 tools/test.py</code>.</li></ol>
<h3>Что означает «без сборки»</h3><p>Страница запускается из готовых HTML/CSS/JS-файлов. Python и Node.js нужны сопровождающим кит для генерации документации, проверки и обновления ресурсов; это не зависимости страницы в браузере.</p>
<h3 id="development--scale">Контракт и тиражирование</h3><p>Целевой масштаб — десятки тысяч строк и больше, отдельные сайты и встраивание в ИИ-среду, анализ и рабочие действия. Сервер фильтрует и считает весь срез, браузер получает готовые агрегаты и одну страницу таблицы. Переключение страницы не меняет смысл KPI и графика.</p><p><a href="reference-dashboard.html">Эталон «Работа служб» ↗</a> · <a href="docs/dashboard-data.md">Контракт данных и API</a> · <a href="docs/reference-server.md">Учебный сервер</a> · <a href="docs/releases.md">Версии и откат</a></p><p>Эталон использует вымышленные данные. Новый слой экспериментальный: до выпуска обязательны сквозная браузерная проверка, реальный источник и проверка прав и команд в приложении. Учебное поручение не создаёт рабочую задачу.</p><h3>Как оценивать готовность</h3><p>Проверяйте статус компонента, ограничения API и реальные сценарии: данные, клавиатуру, темы, размеры экрана, ошибку и восстановление. Статус «экспериментальный» требует отдельной проверки перед использованием. Текущие ограничения и технический долг описаны в <a href="REVIEW.md">REVIEW</a> и <a href="HANDOFF.md">HANDOFF</a>.</p></section>
<section class="sc-sec" id="rules"><h2><span class="sc-doc-emoji" aria-hidden="true">📐</span>Правила сборки</h2><p>Начните с вопроса пользователя, выберите показатели и соберите экран из готовых частей. Данные, действия и состояния проверяются вместе.</p><p><a href="docs/current-state.md">Текущие принятые решения</a></p><p>Каждый ряд должен заполнять доступную ширину: для равноправных виджетов используйте <code>dk-grid--balanced</code>, для пяти КПЭ — <code>dk-grid--five</code>. Не резервируйте место под отсутствующий блок. Источники: <a href="README.md">README</a>, <a href="DECISIONS.md">DECISIONS</a>, <a href="DESIGN-UX-ACCESSIBILITY.md">UX и доступность</a>, <a href="REVIEW.md">REVIEW</a>, <a href="HANDOFF.md">HANDOFF</a>. Поздние утверждённые решения заменяют исторические описания.</p>{rules}</section>
<section class="sc-sec" id="uiux"><h2><span class="sc-doc-emoji" aria-hidden="true">🧭</span>UI/UX и эвристики</h2><p>Основной ответ сразу; детали по задаче. Система берёт на себя проверку ввода, форматирование и сохранение контекста. Одинаковые действия сохраняют названия и поведение между экранами.</p><p>Политика: <a href="UIUX.md">правила, кнопки, состояния и способы проверки</a>. Ниже — критерии проверки интерфейса. Подробный технический реестр предназначен для ревью реализации.</p><div class="dk-tablewrap"><table class="dk-table sc-api"><thead><tr><th scope="col">Эвристика</th><th scope="col">Применение в ките</th></tr></thead><tbody>{heuristics}</tbody></table></div><p>Кнопки: приоритет по задаче, понятный результат, квадратные кнопки-значки, объяснимая недоступность и обратная связь. См. <a href="component-button.html">Кнопка</a> и <a href="component-field.html">Поле и форма</a>.</p></section>
<section class="sc-sec" id="patterns"><h2><span class="sc-doc-emoji" aria-hidden="true">🧩</span>Как выбирать и сочетать компоненты</h2><p>Начните с задачи: что человек выбирает, сравнивает или уточняет. В каждом разделе — подходящие компоненты, частые ошибки и способ проверить результат.</p>{patterns}</section>
<section class="sc-sec" id="design-guidance"><h2><span class="sc-doc-emoji" aria-hidden="true">🎨</span>Визуальные принципы</h2><p>Иерархия, ритм, контраст и состояния помогают читать данные и находить действия. Ниже — способы применить эти принципы в существующей системе токенов.</p>{guidance}</section>
<section class="sc-sec" id="catalog"><h2><span class="sc-doc-emoji" aria-hidden="true">📚</span>Компоненты</h2><p>{len(pages)} компонентов, сгруппированных по задаче. Начните с каркаса и данных, затем добавьте нужные действия. На каждой странице есть пример, критерии выбора, состояния и код.</p>{catalog}</section>
<section class="sc-sec" id="foundations"><h2><span class="sc-doc-emoji" aria-hidden="true">🏗️</span>Основа и каркас</h2><p>Сетка, типографика, иконки и каркас объединяют компоненты в один интерфейс. Здесь — назначение каждой части и ссылки на правила подключения.</p>{foundation}</section>
<section class="sc-sec" id="workflow"><h2><span class="sc-doc-emoji" aria-hidden="true">💬</span>Как работать с ИИ</h2><p>Один сценарий для менеджера, аналитика, дизайнера и разработчика: вы задаёте цель и уточняете результат, помощник использует кит для реализации.</p>
<h3>Что передать</h3><p>Достаточно описать нужный результат и предоставить доступные данные. Если важны аудитория, период, определения показателей или ограничения, добавьте их. Помощник уточнит то, без чего нельзя корректно продолжить.</p>
<h3>Что делает помощник</h3><p>Изучает данные и правила кита, предлагает понятную структуру экрана, выбирает компоненты, подключает расчёты и взаимодействия. Проверяет результат и сообщает о недостающих данных, доступах и непроверенных сценариях.</p>
<h3>Как принять результат</h3><ul class="sc-list"><li>Дашборд отвечает на ваш исходный вопрос.</li><li>Показатели понятны и сходятся с источником; примеры не выданы за реальные данные.</li><li>Фильтры обновляют весь связанный срез, а детализация помогает объяснить результат.</li><li>Помощник показал рабочий экран и назвал ограничения проверки.</li></ul>
<h3>Когда нужен справочник</h3><p>Компоненты, API и правила доступны для помощника и для тех, кто хочет углубиться в детали. Читать их перед постановкой задачи не обязательно.</p><p><a href="#catalog">Компоненты ↗</a> · <a href="#development">Техническое подключение ↗</a> · <a href="#rules">Правила сборки ↗</a></p></section>
</div></div></body></html>'''
